import { randomBytes, timingSafeEqual, createHash } from "node:crypto";

/**
 * Session IDs are generated by the booth (128+ random bits, base64url, so
 * 22+ characters). The server only accepts IDs that look like that, which
 * also makes them safe to use as directory names.
 */
export const SESSION_ID_RE = /^[A-Za-z0-9_-]{22,64}$/;

/** Event IDs are operator-chosen slugs, also used as directory names. */
export const EVENT_ID_RE = /^[a-z0-9](?:[a-z0-9-]{0,62}[a-z0-9])?$/;

/** Design IDs are folder names in DESIGNS_DIR. */
export const DESIGN_ID_RE = /^[a-z0-9](?:[a-z0-9-]{0,62}[a-z0-9])?$/;

export function isSessionId(v: unknown): v is string {
  return typeof v === "string" && SESSION_ID_RE.test(v);
}

export function isEventId(v: unknown): v is string {
  return typeof v === "string" && EVENT_ID_RE.test(v);
}

export function isDesignId(v: unknown): v is string {
  return typeof v === "string" && DESIGN_ID_RE.test(v);
}

export function newSessionId(): string {
  return randomBytes(16).toString("base64url");
}

export function sha256Hex(data: Buffer | string): string {
  return createHash("sha256").update(data).digest("hex");
}

/** Constant-time string comparison for secrets. */
export function safeEqual(a: string, b: string): boolean {
  const ha = createHash("sha256").update(a).digest();
  const hb = createHash("sha256").update(b).digest();
  return timingSafeEqual(ha, hb) && a.length === b.length;
}

/**
 * Pragmatic email check: one @, no whitespace, dotted domain, sane length.
 * Deliberately stricter than RFC 5322 (no quoted local parts, no IP domains).
 */
export function isEmail(v: unknown): v is string {
  if (typeof v !== "string" || v.length > 254) return false;
  return /^[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]{1,64}@(?:[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?\.)+[A-Za-z]{2,63}$/.test(v);
}
